from lib import *
S = SS('w102')
steps = [
    step("TFTP(RFC 1350)只有 5 种报文,都以 2 字节操作码开头:RRQ(1,读请求,文件名 + 0 + 模式 + 0)、WRQ(2)、DATA(3,块号 + 最多 512 字节)、ACK(4,块号)、ERROR(5,错误码 + 信息)。我自己实现了服务器和客户端(服务器的“69 端口”这里用 9400)。读一个 2000 字节的文件:客户端发 RRQ(18 字节,文件 small.txt,模式 octet);服务器**从一个新的端口 9402 回答**(这叫 TID,传输标识),不是请求发往的 9400。依次是 DATA 块 1(512 字节)→ ACK 1 → DATA 块 2(512)→ ACK 2 → DATA 块 3(512)→ ACK 3 → DATA 块 4(464 字节)→ ACK 4。文件 2000 = 3 × 512 + 464:不足 512 字节的 DATA 就是传输结束的标志(如果文件长度恰好是 512 的整数倍,最后要多发一个 0 字节的 DATA)。之后两边只认这一对端口,别的端口来插话会被回 ERROR 5(Unknown transfer ID)。(上面日志里 RRQ 出现两次,是我的记录函数在客户端和服务器两边各记了一次,线上只有一个。)", t=tl(S(1)), mark=lidx(S(1), 'RRQ 文件=small.txt', 'DATA 块号=1', 'DATA 块号=4'), done=lidx(S(1), 'ACK 块号=1', 'ACK 块号=4', '文件 2000 字节', '服务器回应用的端口'), b=bars([['满块 DATA', 516, '516 字节(4 头 + 512)'], ['最后的 DATA', 468, '468 字节(4 头 + 464)'], ['ACK', 4, '4 字节']], 516, mark=[1], done=[0, 2]), kv=KV([['RRQ', '18 字节 → 服务器公开端口'], ['服务器应答', '新端口(TID 9402)'], ['DATA', '3 × 512 + 464 字节'], ['结束标志', '不足 512 字节的 DATA']], ['结束标志'])),
    step("错误:请求一个不存在的文件 nope.txt,服务器回 ERROR 码 1,信息 “File not found”。ERROR 之后传输就结束了,没有重试。", t=tl(S(2)), mark=lidx(S(2), '请求 nope.txt'), done=lidx(S(2), '请求 nope.txt'), kv=KV([['ERROR 码', '1 = File not found'], ['之后', '传输终止']], ['ERROR 码'])),
    step("停等(lock-step):每个 DATA 都要等对应的 ACK 才发下一个,路上永远只有一个块。往返 50 ms(netlab 每方向 25 ms)读 100000 字节:块大小 512(默认)共 196 个 DATA,耗时 9.94 秒,吞吐 10 KB/s,与“196 个块 × 每块一个往返 0.05 秒 = 9.80 秒”几乎吻合。用 RFC 2348 的 blksize 选项协商 1428:客户端在 RRQ 里附上 “blksize / 1428”,服务器用 OACK 回 “blksize / 1428”,客户端再 ACK 块 0;共 71 个 DATA,耗时 3.66 秒,吞吐 27 KB/s。吞吐 ≈ 块大小 ÷ 往返时间,TFTP 在有延迟的链路上很慢,因为它每次只允许一个块在路上。", t=tl(S(3)), mark=lidx(S(3), '块大小  512', '块大小 1428'), done=lidx(S(3), '吞吐 ≈ 块大小'), b=bars([['512 字节块 耗时', 9.94, '9.94 秒'], ['1428 字节块 耗时', 3.66, '3.66 秒']], 10, mark=[1], done=[0]), kv=KV([['块 512', '196 个块,9.94 秒,10 KB/s'], ['块 1428(OACK)', '71 个块,3.66 秒,27 KB/s'], ['限制', '一次一个块,吞吐 ≈ 块大小 ÷ RTT']], ['限制'])),
    step("丢包。重传由两端的超时驱动。块大小 1428(71 个块),0% 丢包:3.65 秒,0 次超时;3% 丢包(netlab 每方向):4.26 秒,客户端超时 0 次,服务器超时重传 1 次,内容仍然正确。多出的 0.61 秒几乎就是一个 0.6 秒的超时——丢一个包(DATA 或 ACK),就要等一个完整的超时才重传,而正常一个往返只要 0.05 秒,所以丢包让 TFTP 的耗时按“超时”而不是按“往返”增长。(只做了一次 3% 的测量,服务器只遇到 1 次丢包。)", t=tl(S(4)), mark=lidx(S(4), '丢包 3%'), done=lidx(S(4), '丢包 0%', '每丢一个包'), b=bars([['0% 丢包', 3.65, '3.65 秒'], ['3% 丢包', 4.26, '4.26 秒']], 4.3, mark=[1], done=[0]), kv=KV([['0% 丢包', '3.65 秒,0 次超时'], ['3% 丢包', '4.26 秒,服务器重传 1 次'], ['一次丢包的代价', '≈ 一个超时(0.6 秒),正常往返只有 0.05 秒']], ['一次丢包的代价'])),
]
A = mkartw('w102', 102, '网络协议,TFTP,UDP,停等,TID,blksize,真实验证,动画演示',
    '自己实现 TFTP:5 种报文、服务器从新端口(TID)回答、不足 512 字节的 DATA 是结束标志;停等让 100 KB 在 50 ms 往返下需要 9.94 秒(10 KB/s),协商 blksize=1428 后降到 3.66 秒;丢一个包就多等一个 0.6 秒的超时。',
    'TFTP 是最简单的文件传输协议:5 种报文、没有认证、一次只发一个块等一个 ACK。它简单到可以写进网卡的启动固件里,所以至今仍用来网络启动和配置设备。这篇自己实现它,看清它的每个报文、为什么在有延迟的链路上那么慢,以及 blksize 选项能救多少。',
    [('9.94 → 3.66 秒', '50 ms 往返下读 100000 字节,块大小 512 与协商 1428 的耗时'), ('516 字节', '一个满块 DATA 报文的长度(4 字节头 + 512 字节数据)'), ('0.6 秒', '丢一个包之后要多等的超时(正常往返只有 0.05 秒)')],
    [('5 种报文', '<p>RRQ / WRQ / DATA / ACK / ERROR;服务器每个传输换一个新端口(TID)。</p>'),
     ('结束与错误', '<p>不足 512 字节的 DATA 表示传输结束;文件不存在回 ERROR 1。</p>'),
     ('停等', '<p>吞吐 ≈ 块大小 ÷ 往返时间;blksize 选项(OACK)把 512 提升到 1428,耗时降到 37%。</p>'),
     ('丢包', '<p>重传靠超时,一次丢包多等一个完整超时。</p>')],
    steps,
    [ENV_W + '。TFTP 服务器和客户端都是我自己写的最小实现(只支持 RRQ 和 blksize 选项,没有 WRQ、没有 tsize / timeout 选项、没有重传上限之外的复杂逻辑),全在本机 lo0;“69 端口”用 9400 代替,数据端口也在 netlab 范围内;丢包测试只做了一次',
     '没有验证:WRQ 上传;netascii 模式;RFC 7440 的 windowsize(滑动窗口);“魔法学徒综合征”(重复 ACK 引起的重复 DATA)的防范;PXE 启动用 TFTP 的真实流程;TFTP 没有认证带来的安全问题(任意读取服务器文件的目录穿越);真实 TFTP 服务器(tftpd-hpa 等)的行为'],
    'TFTP')
